/// Channel for real-time chat messaging.
/// Supports team-scoped and user-scoped threads with keyed, transient, and direct
/// thread access patterns.
public final class ApiChatChannel: Sendable {
    public let channel: Channel
    public let joinResponse: JSONValue?

    public init(channel: Channel, joinResponse: JSONValue? = nil) {
        self.channel = channel
        self.joinResponse = joinResponse
    }

    /// Join a team-scoped thread by ID
    public static func topicTeamThread(teamId: String, threadId: String) -> String {
        return "api:chat:team:\(teamId):thread:\(threadId)"
    }

    /// Join a team-scoped thread by ID
    public static func joinTeamThread(socket: Socket, teamId: String, threadId: String, afterCursor: String? = nil, beforeCursor: String? = nil, includeMetadata: Bool? = nil, limit: Int? = nil) async throws -> ApiChatChannel {
        let topic = topicTeamThread(teamId: teamId, threadId: threadId)
        let channel = socket.channel(topic)
        var payload: [String: JSONValue] = [:]
        if let afterCursor = afterCursor {
            payload["after_cursor"] = .string(afterCursor)
        }
        if let beforeCursor = beforeCursor {
            payload["before_cursor"] = .string(beforeCursor)
        }
        if let includeMetadata = includeMetadata {
            payload["include_metadata"] = .bool(includeMetadata)
        }
        if let limit = limit {
            payload["limit"] = .int(limit)
        }
        let joinResponse = try await channel.join(.object(payload))
        return ApiChatChannel(channel: channel, joinResponse: joinResponse)
    }

    /// Join or create a team-scoped keyed thread
    public static func topicTeamKeyed(teamId: String, key: String) -> String {
        return "api:chat:team:\(teamId):key:\(key)"
    }

    /// Join or create a team-scoped keyed thread
    public static func joinTeamKeyed(socket: Socket, teamId: String, key: String, afterCursor: String? = nil, beforeCursor: String? = nil, includeMetadata: Bool? = nil, limit: Int? = nil) async throws -> ApiChatChannel {
        let topic = topicTeamKeyed(teamId: teamId, key: key)
        let channel = socket.channel(topic)
        var payload: [String: JSONValue] = [:]
        if let afterCursor = afterCursor {
            payload["after_cursor"] = .string(afterCursor)
        }
        if let beforeCursor = beforeCursor {
            payload["before_cursor"] = .string(beforeCursor)
        }
        if let includeMetadata = includeMetadata {
            payload["include_metadata"] = .bool(includeMetadata)
        }
        if let limit = limit {
            payload["limit"] = .int(limit)
        }
        let joinResponse = try await channel.join(.object(payload))
        return ApiChatChannel(channel: channel, joinResponse: joinResponse)
    }

    /// Join a team-scoped transient (ephemeral) thread
    public static func topicTeamTransient(teamId: String, key: String) -> String {
        return "api:chat:team:\(teamId):transient:\(key)"
    }

