    /// Broadcast when a new message is added to a thread
    /// Payloads that fail to decode as the declared type are dropped.
    @discardableResult
    public func onMessageAdded(_ callback: @escaping @Sendable (ApiChatMessageAddedPayload) -> Void) -> @Sendable () -> Void {
        return channel.on("message_added") { payload in
            guard let decoded = try? payload.decode(ApiChatMessageAddedPayload.self) else { return }
            callback(decoded)
        }
    }

    /// Broadcast when a message is updated or removed
    /// Payloads that fail to decode as the declared type are dropped.
